<script setup lang="ts">import { inject, onMounted, ref, type Ref } from "vue"; import { listTechnicians, updateStatus, updateTechnical, type Repair, type RepairStatus } from "../../api"; const repair = inject<Ref<Repair | null>>("repair"); const technicians = ref<{ id: string; displayName: string }[]>([]); const diagnosis = ref(""); const technicianId = ref(""); onMounted(async () => { technicians.value = await listTechnicians(); diagnosis.value = repair?.value?.diagnosis ?? ""; technicianId.value = repair?.value?.technicianId ?? ""; }); async function save() { if (repair?.value) repair.value = await updateTechnical(repair.value.id, { technicianId: technicianId.value || undefined, diagnosis: diagnosis.value || undefined }); } async function status(event: Event) { if (repair?.value) repair.value = await updateStatus(repair.value.id, (event.target as HTMLSelectElement).value as RepairStatus); }</script><template><form v-if="repair" class="entity-form" @submit.prevent="save"><fieldset><legend>Diagnostico tecnico</legend><label>Estado<select :value="repair.status" @change="status"><option v-for="item in ['received','diagnosing','quoted','approved','repairing','testing','repaired','delivered','unrepairable','cancelled']" :key="item" :value="item">{{ item }}</option></select></label><label>Tecnico<select v-model="technicianId"><option value="">Sin asignar</option><option v-for="technician in technicians" :key="technician.id" :value="technician.id">{{ technician.displayName }}</option></select></label><label>Diagnostico<textarea v-model="diagnosis" rows="5" /></label></fieldset><footer><button>Guardar diagnostico</button></footer></form></template>